{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Human PET with [11C]metoclopramide showed substantial baseline brain distribution (V_T 2.1 mL/cm3), demonstrating meaningful CNS access despite P-gp efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "In mice, 131I-MIP-1145 crossed the blood-brain barrier with brain uptake of 0.6-0.8 % ID/g after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In rats, [11C]6 showed low whole-brain uptake (0.189 % ID/g at 5 min) and was efflux-sensitive, indicating poor CNS access for that analogue.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted pass: direct in vivo and human PET evidence from several similar molecules supports meaningful BBB crossing, including one efflux substrate with substantial brain distribution. Negative low-uptake/efflux records are present but do not outweigh the direct positive CNS-access evidence, especially given the low structural similarities and mixed data.",
  "evidence_gaps": [
    "Morgan similarities are low (0.23-0.25), limiting transferability to the query.",
    "Direct outcomes are mixed across similar molecules, with both clear brain uptake and low-uptake/efflux-limited examples.",
    "Brain-to-plasma ratios around 0.16-0.2 are interpreted inconsistently across records.",
    "Efflux-substrate status alone does not define CNS access, but its contribution to the negative records is not fully separable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

